    private static final int READ_TIMEOUT = 5000;
    private static final int MAX_DESCRIPTION_LENGTH = 200;
    private static final String DEFAULT_CHARSET = "UTF-8";
    private static final String USER_AGENT = "Mozilla/5.0 (compatible; UrlPreviewBot/1.0)";

    public String getUrlContentPreview(String urlString) {
        if (urlString == null || urlString.trim().isEmpty()) {
            return "Error: URL is null or empty";
        }

        HttpURLConnection connection = null;
        try {
            URL url = new URL(urlString);
            connection = (HttpURLConnection) url.openConnection();
            connection.setRequestMethod("GET");
            connection.setConnectTimeout(CONNECT_TIMEOUT);
            connection.setReadTimeout(READ_TIMEOUT);
            connection.setRequestProperty("User-Agent", USER_AGENT);
            connection.setInstanceFollowRedirects(true);

            int responseCode = connection.getResponseCode();
            if (responseCode != HttpURLConnection.HTTP_OK) {
                return "Error: Unable to fetch URL content (HTTP " + responseCode + ")";
            }

            String charset = extractCharset(connection.getContentType());

            String html;
            try (BufferedReader reader = new BufferedReader(
                    new InputStreamReader(connection.getInputStream(), charset))) {
                html = reader.lines().collect(Collectors.joining("\n"));
            }

            if (html == null || html.trim().isEmpty()) {
                return "Error: Empty response from URL";
            }

            String title = extractTitle(html);
            String description = extractMetaDescription(html);

            if (description == null || description.trim().isEmpty()) {
                String textContent = stripHtmlTags(html);
                if (textContent.length() > MAX_DESCRIPTION_LENGTH) {
                    description = textContent.substring(0, MAX_DESCRIPTION_LENGTH);
                } else {
                    description = textContent;
                }
            }

            title = title != null ? title.trim() : "No Title";
            description = description != null ? description.trim() : "No Description";

            return "Title: " + title + "\nDescription: " + description;

        } catch (Exception e) {
            return "Error: " + e.getMessage();
        } finally {
            if (connection != null) {
                connection.disconnect();
            }
        }
    }

    private String extractCharset(String contentType) {
        if (contentType != null) {
            for (String param : contentType.split(";")) {
                param = param.trim();
                if (param.toLowerCase().startsWith("charset=")) {
                    return param.substring("charset=".length()).trim();
                }
            }
        }
        return DEFAULT_CHARSET;
    }

    private String extractTitle(String html) {
        Pattern pattern = Pattern.compile(
                "<title[^>]*>(.*?)</title>",
                Pattern.CASE_INSENSITIVE | Pattern.DOTALL
        );
        Matcher matcher = pattern.matcher(html);
        if (matcher.find()) {
            return decodeHtmlEntities(matcher.group(1).trim());
        }
        return null;
    }

    private String extractMetaDescription(String html) {
        // Pattern 1: name before content
        Pattern pattern1 = Pattern.compile(
                "<meta\\s+[^>]*?name\\s*=\\s*[\"']description[\"'][^>]*?content\\s*=\\s*[\"']([^\"']*)[\"'][^>]*?/?>",
                Pattern.CASE_INSENSITIVE | Pattern.DOTALL
        );
        Matcher matcher = pattern1.matcher(html);
        if (matcher.find()) {
            String desc = decodeHtmlEntities(matcher.group(1).trim());
            if (!desc.isEmpty()) {
                return desc;
            }
        }

        // Pattern 2: content before name
        Pattern pattern2 = Pattern.compile(
                "<meta\\s+[^>]*?content\\s*=\\s*[\"']([^\"']*)[\"'][^>]*?name\\s*=\\s*[\"']description[\"'][^>]*?/?>",
                Pattern.CASE_INSENSITIVE | Pattern.DOTALL
        );
        matcher = pattern2.matcher(html);
        if (matcher.find()) {
            String desc = decodeHtmlEntities(matcher.group(1).trim());
            if (!desc.isEmpty()) {
                return desc;
            }
        }

        return null;
    }

    private String stripHtmlTags(String html) {
        // Remove script and style blocks entirely
        String result = html.replaceAll("(?is)<(script|style|noscript)[^>]*>.*?</\\1>", " ");
        // Remove all remaining HTML tags
        result = result.replaceAll("<[^>]+>", " ");
        // Decode HTML entities
        result = decodeHtmlEntities(result);
        // Normalize whitespace
        result = result.replaceAll("\\s+", " ").trim();
        return result;
    }

    private String decodeHtmlEntities(String text) {
        if (text == null) {
            return null;
        }
        return text
                .replace("&amp;", "&")
                .replace("&lt;", "<")
                .replace("&gt;", ">")
                .replace("&quot;", "\"")
                .replace("&#39;", "'")
                .replace("&apos;", "'")
                .replace("&nbsp;", " ")
                .replace("&#160;", " ")
                .replace("&mdash;", "—")
                .replace("&ndash;", "–")
                .replace("&hellip;", "…")
                .replace("&copy;", "©")
                .replace("&reg;", "®")
                .replace("&trade;", "™");
    }
