                for (InetAddress addr : addresses) {
                    if (isPrivateOrReservedIP(addr)) {
                        return "Error: Access to internal network is not allowed";
                    }
                }

                // 3. Open connection and disable automatic redirect following
                URLConnection connection = currentUrl.openConnection();
                connection.setConnectTimeout(5000); // 5 seconds timeout
                connection.setReadTimeout(5000);    // 5 seconds timeout

                if (connection instanceof HttpURLConnection) {
                    HttpURLConnection httpConnection = (HttpURLConnection) connection;
                    httpConnection.setInstanceFollowRedirects(false);

                    int status = httpConnection.getResponseCode();

                    // Handle redirects manually to re-validate the target URL
